import type { ReactNode } from "react"

import { cn } from "@ziwako/ui/utils"

import { IntroHeader } from "./intro-header"
import { VideoEmbed, type VideoEmbedProps } from "./video-embed"
import { type HeadlineSegment } from "./headline-chips-text"

export interface VideoFeatureProps {
  eyebrow?: string
  title: ReactNode | (string | HeadlineSegment)[]
  /** Note courte affichée à droite du titre. */
  note?: string
  video: VideoEmbedProps
  className?: string
}

/**
 * Preset « Video Tour » : eyebrow + titre (gauche) + note (droite) puis vidéo.
 */
export function VideoFeature({
  eyebrow,
  title,
  note,
  video,
  className,
}: VideoFeatureProps) {
  return (
    <section className={cn("py-16 md:py-24", className)}>
      <div className="mx-auto w-full max-w-7xl px-4 sm:px-6 lg:px-8">
        <IntroHeader
          badge={eyebrow}
          title={title}
          actions={
            note ? (
              <p className="max-w-xs text-sm text-muted-foreground">{note}</p>
            ) : undefined
          }
          layout="split"
          align="left"
          size="lg"
        />
        <VideoEmbed {...video} className="mt-10" />
      </div>
    </section>
  )
}

import type { ReactNode } from "react"
import Link from "next/link"

import { Button } from "@ziwako/ui/button"
import { cn } from "@ziwako/ui/utils"

import { HeadlineChipsText, type HeadlineSegment } from "./headline-chips-text"

export interface IntroHeaderProps {
  badge?: string
  /** Titre rich : `ReactNode` ou segments (`headline-chips` → chips/highlight). */
  title: ReactNode | (string | HeadlineSegment)[]
  description?: string
  primaryCta?: { label: string; href: string }
  secondaryCta?: { label: string; href: string }
  /** Slot aligné à droite (actions). Active le layout "split". */
  actions?: ReactNode
  /**
   * `stack` (défaut) : tout empilé.
   * `split` : bloc titre à gauche, `actions` à droite.
   */
  layout?: "stack" | "split"
  align?: "center" | "left"
  size?: "md" | "lg" | "xl"
  className?: string
}

const SIZE_CLASSES: Record<NonNullable<IntroHeaderProps["size"]>, string> = {
  md: "text-2xl sm:text-3xl md:text-4xl",
  lg: "text-3xl sm:text-4xl md:text-5xl",
  xl: "text-4xl sm:text-5xl md:text-6xl",
}

/**
 * En-tête d'introduction de section : badge, titre rich (chips/highlight),
 * description, double CTA et slot `actions` (layout split optionnel).
 */
export function IntroHeader({
  badge,
  title,
  description,
  primaryCta,
  secondaryCta,
  actions,
  layout = "stack",
  align = "center",
  size = "lg",
  className,
}: IntroHeaderProps) {
  const isCenter = align === "center" && layout === "stack"

  const titleBlock = (
    <>
      {badge ? (
        <span className="inline-flex items-center rounded-full bg-muted px-3 py-1 text-xs font-medium tracking-wide text-muted-foreground uppercase">
          {badge}
        </span>
      ) : null}

      <h2
        className={cn(
          "mt-4 text-balance font-extrabold tracking-tight text-foreground",
          SIZE_CLASSES[size]
        )}
      >
        {Array.isArray(title) ? <HeadlineChipsText segments={title} /> : title}
      </h2>

      {description ? (
        <p
          className={cn(
            "mt-4 text-lg text-muted-foreground",
            isCenter && "mx-auto max-w-2xl"
          )}
        >
          {description}
        </p>
      ) : null}

      {primaryCta || secondaryCta ? (
        <div
          className={cn(
            "mt-8 flex flex-col gap-3 sm:flex-row",
            isCenter ? "items-center justify-center" : "items-start"
          )}
        >
          {primaryCta ? (
            <Button className="rounded-2xl px-6" asChild>
              <Link href={primaryCta.href}>{primaryCta.label}</Link>
            </Button>
          ) : null}
          {secondaryCta ? (
            <Button variant="outline" className="rounded-2xl px-6" asChild>
              <Link href={secondaryCta.href}>{secondaryCta.label}</Link>
            </Button>
          ) : null}
        </div>
      ) : null}
    </>
  )

  if (layout === "split" && actions) {
    return (
      <div
        className={cn(
          "flex flex-col gap-6 md:flex-row md:items-end md:justify-between",
          className
        )}
      >
        <div className="max-w-3xl">{titleBlock}</div>
        <div className="flex shrink-0 items-center gap-3">{actions}</div>
      </div>
    )
  }

  return (
    <div
      className={cn(
        isCenter ? "mx-auto max-w-3xl text-center" : "max-w-3xl text-left",
        className
      )}
    >
      {titleBlock}
      {actions ? <div className="mt-6 flex items-center gap-3">{actions}</div> : null}
    </div>
  )
}

import { cn } from "@ziwako/ui/utils"

export interface VideoEmbedProps {
  /** URL de la source (iframe YouTube/Vimeo ou fichier vidéo). */
  src: string
  /** `iframe` (défaut) ou `video` (HTML5 `<video controls>`). */
  type?: "iframe" | "video"
  poster?: string
  title?: string
  aspect?: string
  className?: string
}

/**
 * Lecteur vidéo responsive : iframe (YouTube/Vimeo…) ou HTML5 `<video>`.
 * Ratio par défaut `aspect-video`.
 */
export function VideoEmbed({
  src,
  type = "iframe",
  poster,
  title,
  aspect = "aspect-video",
  className,
}: VideoEmbedProps) {
  return (
    <div
      className={cn(
        "relative w-full overflow-hidden rounded-3xl bg-muted",
        aspect,
        className
      )}
    >
      {type === "video" ? (
        <video
          src={src}
          poster={poster}
          controls
          playsInline
          className="size-full object-cover"
        />
      ) : (
        <iframe
          src={src}
          title={title ?? "Video"}
          allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share"
          allowFullScreen
          loading="lazy"
          className="absolute inset-0 size-full"
        />
      )}
    </div>
  )
}

import type { ComponentType } from "react"
import Image from "next/image"

import { cn } from "@ziwako/ui/utils"

export type ChipColor =
  | "primary"
  | "secondary"
  | "blue"
  | "orange"
  | "green"
  | "amber"
  | "red"
  | "purple"
  | "pink"
  | "teal"
  | "violet"
  | "yellow"
  | "muted"

export type ChipTone = "subtle" | "solid"

/** Pattern A — fond clair + texte foncé. */
const CHIP_SUBTLE: Record<ChipColor, string> = {
  primary: "bg-blue-subtle text-blue-fg",
  secondary: "bg-orange-subtle text-orange-fg",
  blue: "bg-blue-subtle text-blue-fg",
  orange: "bg-orange-subtle text-orange-fg",
  green: "bg-green-subtle text-green-fg",
  amber: "bg-amber-subtle text-amber-fg",
  red: "bg-red-subtle text-red-fg",
  purple: "bg-purple-subtle text-purple-fg",
  pink: "bg-pink-subtle text-pink-fg",
  teal: "bg-teal-subtle text-teal-fg",
  violet: "bg-violet-subtle text-violet-fg",
  yellow: "bg-yellow-subtle text-yellow-fg",
  muted: "bg-muted text-foreground",
}

/** Pattern B — fond vif + texte contraste. */
const CHIP_SOLID: Record<ChipColor, string> = {
  primary: "bg-primary text-primary-foreground",
  secondary: "bg-secondary text-secondary-foreground",
  blue: "bg-blue-solid text-blue-contrast",
  orange: "bg-orange-solid text-orange-contrast",
  green: "bg-green-solid text-green-contrast",
  amber: "bg-amber-solid text-amber-contrast",
  red: "bg-red-solid text-red-contrast",
  purple: "bg-purple-solid text-purple-contrast",
  pink: "bg-pink-solid text-pink-contrast",
  teal: "bg-teal-solid text-teal-contrast",
  violet: "bg-violet-solid text-violet-contrast",
  yellow: "bg-yellow-solid text-yellow-contrast",
  muted: "bg-muted-foreground text-background",
}

export function chipStyle(color: ChipColor = "muted", tone: ChipTone = "subtle") {
  return (tone === "solid" ? CHIP_SOLID : CHIP_SUBTLE)[color]
}

interface SegmentBase {
  color?: ChipColor
  tone?: ChipTone
}

export type HeadlineSegment =
  | { type: "text"; value: string; className?: string }
  | ({ type: "highlight"; value: string; className?: string } & SegmentBase)
  | ({ type: "pill"; value: string } & SegmentBase)
  | ({ type: "avatar"; src: string; alt?: string } & SegmentBase)
  | ({ type: "image"; src: string; alt?: string; className?: string } & SegmentBase)
  | ({ type: "icon"; icon: ComponentType<{ className?: string }> } & SegmentBase)

export interface HeadlineChipsTextProps {
  segments: (string | HeadlineSegment)[]
  className?: string
}

/**
 * Rendu inline des segments de titre (texte + chips). À placer dans un
 * `<h1>`/`<h2>`/`<p>` — hérite de la typographie du parent.
 */
export function HeadlineChipsText({ segments, className }: HeadlineChipsTextProps) {
  return (
    <span className={className}>
      {segments.map((segment, index) => {
        const seg: HeadlineSegment =
          typeof segment === "string"
            ? { type: "text", value: segment }
            : segment

        switch (seg.type) {
          case "text":
            return (
              <span key={index} className={seg.className}>
                {seg.value}{" "}
              </span>
            )
          case "highlight":
            return (
              <span
                key={index}
                className={cn(
                  "inline rounded-lg px-[0.15em] align-middle",
                  chipStyle(seg.color ?? "blue", seg.tone ?? "subtle"),
                  seg.className
                )}
              >
                {seg.value}
              </span>
            )
          case "pill":
            return (
              <span
                key={index}
                className={cn(
                  "mx-1 inline-flex items-center rounded-full px-[0.6em] py-[0.05em] align-middle text-[0.8em]",
                  chipStyle(seg.color, seg.tone)
                )}
              >
                {seg.value}
              </span>
            )
          case "avatar":
            return (
              <span
                key={index}
                className={cn(
                  "mx-1 inline-block size-[1.3em] overflow-hidden rounded-full align-middle",
                  chipStyle(seg.color, seg.tone)
                )}
              >
                <Image
                  src={seg.src}
                  alt={seg.alt ?? ""}
                  width={128}
                  height={128}
                  className="size-full object-cover"
                />
              </span>
            )
          case "image":
            return (
              <span
                key={index}
                className={cn(
                  "mx-1 inline-block h-[1.3em] w-[2.1em] overflow-hidden rounded-full align-middle",
                  chipStyle(seg.color, seg.tone),
                  seg.className
                )}
              >
                <Image
                  src={seg.src}
                  alt={seg.alt ?? ""}
                  width={160}
                  height={96}
                  className="size-full object-cover"
                />
              </span>
            )
          case "icon": {
            const Icon = seg.icon
            return (
              <span
                key={index}
                className={cn(
                  "mx-1 inline-flex size-[1.3em] items-center justify-center rounded-full align-middle",
                  chipStyle(seg.color, seg.tone)
                )}
              >
                <Icon className="size-[0.7em]" />
              </span>
            )
          }
          default:
            return null
        }
      })}
    </span>
  )
}
